/** ความสามารถ "อ่านไฟล์ในเครื่อง" ที่ transport ฉีดเข้ามา (stdio ส่งของจริง, remote ส่ง null) */
export interface LocalFs {
  /** โยน error ที่มี .code (ENOENT/EACCES/…) แบบเดียวกับ node:fs */
  stat(p: string): Promise<{ size: number; isFile: boolean }>;
  read(p: string): Promise<Uint8Array>;
  /** ทำ path ให้เป็นสัมบูรณ์เทียบกับ base (หรือ cwd ถ้าไม่ส่ง base) */
  resolve(p: string, base?: string): string;
  basename(p: string): string;
  /** path จริงหลังคลี่ symlink ทุกชั้น — โยน error ที่มี .code (ENOENT) เหมือน node:fs */
  realpath(p: string): Promise<string>;
  /** candidate อยู่ใต้ root ไหม — ทั้งคู่ต้องสัมบูรณ์แล้ว (ดู fsGuard.makeIsInside — ถูกทั้ง posix/win32) */
  isInside(root: string, candidate: string): boolean;
}

export interface ToolContext {
  client: ArtemisClient;
  cfg: Config;
  fs: LocalFs | null;
  fetchImpl?: FetchLike;
}

/** annotations ตามสเปก MCP — บอก client ว่า tool นี้ปลอดภัยแค่ไหน */
export interface ToolAnnotations {
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
  idempotentHint?: boolean;
  openWorldHint?: boolean;
}

export interface ArtemisToolDef {
  name: string;
  config: {
    title: string;
    description: string;
    inputSchema: z.ZodRawShape;
    annotations: ToolAnnotations;
  };
  handler: (args: Record<string, unknown>) => Promise<ToolResult>;
}

// ── ตัวช่วยจัดรูปแบบผลลัพธ์ ──────────────────────────────────────────────────
//
// เส้นลิสต์ตอบเป็น "หนึ่งบรรทัดต่อรายการ" ไม่ใช่ JSON — ประหยัด token กว่ามาก
// และ model อ่านง่ายพอ ๆ กัน · ผู้เรียกที่ต้องประมวลผลต่อขอ format:"json" ได้

const FORMAT = z
  .enum(["table", "json"])
  .optional()
  .describe("table (ปริยาย) = หนึ่งบรรทัดต่อรายการ ประหยัด token · json = ข้อมูลดิบไว้ประมวลผลต่อ");

/**
 * ผลลัพธ์ json ของทุก tool — แปลงช่องเวลาที่รู้จัก (epoch ms) เป็น ISO 8601 +07:00 ก่อนเสมอ (ART-278)
 * ทำที่จุดเดียวนี้ เพื่อไม่ให้ tool ใหม่ลืมแปลงแล้วคืน epoch ms ทศนิยมให้ model เดาเอง
 */
function asJson(value: unknown): string {
  return JSON.stringify(withIsoTimes(value), null, 0);
}

/** หัวบรรทัดที่ทุกรายการงานใช้ร่วม: รหัส [สถานะ] (priority) ชนิด ชื่อ แต้ม */
function headBits(t: { key: string; status: string; priority: string; type: string; title: string; storyPoints: number | null }): string[] {
  const bits = [t.key, `[${t.status}]`, `(${t.priority})`, t.type, t.title];
  if (t.storyPoints !== null) bits.push(`${t.storyPoints}pt`);
  return bits;
}

function ticketLine(t: TicketSummary): string {
  const bits = headBits(t);
  if (t.sprintName !== null) bits.push(`sprint:${t.sprintName}`);
  if (t.parentKey !== null) bits.push(`↳${t.parentKey}`);
  if (t.flagged) bits.push("⚑");
  if (t.archived) bits.push("(archived)");
  bits.push(...boardBits(t));
  return bits.join("  ");
}

/**
 * ฟิลด์สรุปบอร์ดของ ART-278 — มีเฉพาะเส้นที่ server ส่งมา (list_tickets / board_snapshot)
 * เส้นอื่นที่ใช้ ticketLine ร่วม (sprint/backlog) ไม่มีฟิลด์เหล่านี้ → ข้ามเงียบ ๆ ไม่พิมพ์ "undefined"
 */
function boardBits(t: TicketSummary): string[] {
  const bits: string[] = [];
  if (t.assignees !== undefined) bits.push(t.assignees.length > 0 ? `assignees:${t.assignees.join(",")}` : "assignees:-");
  if (t.reporter) bits.push(`by:${t.reporter}`);
  if (t.labels !== undefined && t.labels.length > 0) bits.push(t.labels.map((l) => `#${l}`).join(" "));
  if (t.startDate) bits.push(`start:${t.startDate}`);
  if (t.assignees !== undefined && t.dueDate !== null) bits.push(`due:${t.dueDate}`);
  if (t.childCount !== undefined && t.childCount > 0) bits.push(`sub:${t.childOpenCount ?? 0}/${t.childCount} open`);
  const at = (label: string, ms: number | null | undefined) => {
    const v = isoBkk(ms);
    if (v !== null) bits.push(`${label}:${v}`);
  };
  at("created", t.createdAt);
  at("updated", t.updatedAt);
  at("inStatus", t.statusChangedAt);
  at("comment", t.lastCommentAt);
  return bits;
}

/** งานลูกใน board_snapshot — ย่อหน้า 2 ช่องใต้ใบแม่ */
function childLine(c: SnapshotChild): string {
  const bits = [`  ↳ ${c.key}`, `[${c.status}]`, c.title];
  bits.push(c.assignees.length > 0 ? `assignees:${c.assignees.join(",")}` : "assignees:-");
  if (c.labels.length > 0) bits.push(c.labels.map((l) => `#${l}`).join(" "));
  if (c.dueDate !== null) bits.push(`due:${c.dueDate}`);
  const v = isoBkk(c.statusChangedAt);
  if (v !== null) bits.push(`inStatus:${v}`);
  return bits.join("  ");
}

/**
 * รายละเอียดของเหตุการณ์ใน list_activity ตาม action — ไม่ใช้ลูกศรกับสิ่งที่ไม่ได้ "เปลี่ยนจาก A เป็น B"
 * (เดิม `- → a@x` ของ assign อ่านเหมือน "เปลี่ยนผู้รับผิดชอบจากไม่มีเป็น a" ทั้งที่งานอาจมีคนอื่นอยู่แล้ว)
 * ความหมายของ field/from/to ต่อ action ตรงกับคำอธิบายของ tool และ openapi (ActivityEvent)
 */
function activityDetail(e: ActivityEvent): string {
  const arrow = `${e.from ?? "-"} → ${e.to ?? "-"}`;
  switch (e.action) {
    case "assign":
    case "label_add":
      return `+${e.to ?? "-"}`;
    case "unassign":
    case "label_remove":
      return `-${e.from ?? "-"}`;
    case "field":
      return `field:${e.field ?? "-"} ${arrow}`;
    case "due_rollup":
    case "start_rollup":
    case "due_recalc":
    case "start_recalc":
      return `via:${e.field ?? "-"} ${arrow}`;
    case "sprint_remove":
      return `${e.field ?? "sprint:-"} ${arrow}`;
    case "moved_project":
      return e.field === null ? arrow : `${arrow} oldKey:${e.field}`;
    case "create":
      return e.to === null ? "" : `"${e.to}"`;
    case "comment":
    case "archive":
    case "restore":
      return "";
    default: // status และ action ที่ tool รุ่นนี้ยังไม่รู้จัก
      return e.field === null ? arrow : `${e.field} ${arrow}`;
  }
}

/** 1 บรรทัดต่อเหตุการณ์ของ list_activity: เวลา  รหัส  action  รายละเอียด  by:ผู้กระทำ */
function activityLine(e: ActivityEvent): string {
  // key = "" ได้ (แถวย้ายออกที่ไม่รู้รหัสเดิม — ดู openapi ActivityEvent) → "-" ไม่ให้คอลัมน์เลื่อน
  const bits = [isoBkk(e.at) ?? "-", e.key || "-", e.action];
  const detail = activityDetail(e);
  if (detail !== "") bits.push(detail);
  bits.push(`by:${e.actor ?? "-"}`);
  return bits.join("  ");
}

/** 1 บรรทัดต่องานใน My Work — แบบ ticketLine + วันส่ง/ป้าย/ลิงก์ (รายการข้ามโปรเจกต์ เปิดต่อด้วยลิงก์ได้เลย) */
function myWorkLine(cfg: Config, r: MyWorkRow): string {
  const bits = headBits(r);
  if (r.dueDate !== null) bits.push(`due:${r.dueDate}`);
  if (r.parentKey !== null) bits.push(`↳${r.parentKey}`);
  if (r.flagged) bits.push("⚑");
  if (r.labels.length > 0) bits.push(r.labels.map((l) => `#${l}`).join(" "));
  const url = ticketUrl(cfg, r.key);
  if (url !== undefined) bits.push(url);
  return bits.join("  ");
}

/**
 * ท้ายรายการ: บอก hasMore/nextCursor **ทุกครั้ง** (ART-278) — รวมหน้าสุดท้ายและหน้าว่าง
 * ไม่บอกแปลว่า model ต้องเดาว่าเห็นครบแล้วหรือยัง ซึ่งเคยทำให้ agent หยุดอ่านกลางทาง
 */
function pageFooter(page: Page<unknown>): string {
  if (!page.hasMore) return `\n\n(แสดง ${page.data.length} รายการ · hasMore=false · nextCursor=null — ครบแล้ว)`;
  return (
    `\n\n(แสดง ${page.data.length} รายการ · hasMore=true · nextCursor="${page.nextCursor}" — ` +
    `ยังมีต่อ เรียกซ้ำด้วย cursor="${page.nextCursor}")`
  );
}

function renderList<T>(
  page: Page<T>,
  format: string | undefined,
  line: (item: T) => string,
  emptyMsg: string,
): ToolResult {
  if (format === "json") return ok(asJson(page));
  if (page.data.length === 0) {
    // หน้าว่างที่ยังมีต่อ ≠ "ไม่มีงาน" — ห้ามตอบ emptyMsg ไม่งั้น agent สรุปผิดแล้วหยุดอ่าน (ART-277)
    const head = page.hasMore ? "หน้านี้ไม่มีรายการที่ตรง แต่ข้อมูลยังไม่หมด" : emptyMsg;
    return ok(head + pageFooter(page));
  }
  return ok(page.data.map(line).join("\n") + pageFooter(page));
}

