// ── เวลา: ISO 8601 เขตเวลาไทยเสมอ (ART-278) ─────────────────────────────────
//
// REST คืน epoch ms (คงไว้ให้ระบบอื่นที่เรียกอยู่แล้ว) · ชั้น MCP แปลงให้ model อ่านได้ตรง ๆ
// ทีมทำงานเวลาไทย จึงใช้ +07:00 (ประเทศไทยไม่มี daylight saving — offset คงที่)

const BKK_OFFSET_MS = 7 * 60 * 60 * 1000;

/** epoch ms → "2026-11-18T10:04:05+07:00" · null/undefined → null */
export function isoBkk(ms: number | null | undefined): string | null {
  // นอกช่วงที่ Date รองรับ (±8.64e15) toISOString โยน RangeError ทั้ง tool — คืน null แทน
  if (ms === null || ms === undefined || !Number.isFinite(ms) || Math.abs(ms) > 8.64e15 - BKK_OFFSET_MS) return null;
  return new Date(Math.floor(ms / 1000) * 1000 + BKK_OFFSET_MS).toISOString().replace(/\.\d{3}Z$/, "+07:00");
}

/** ช่องเวลาที่ REST คืนเป็น epoch ms (ทุก endpoint) */
const TIME_KEYS = new Set([
  "createdAt",
  "updatedAt",
  "statusChangedAt",
  "lastCommentAt",
  "editedAt",
  "openedAt",
  "mergedAt",
  "uploadedAt",
  "at", // ART-279: แถวของ list_activity
]);

/** ไล่ทั้งก้อน (object/array ซ้อน) แปลงเฉพาะช่องเวลาที่เป็นตัวเลข — ช่องอื่นคงเดิมทุกตัว */
function withIsoTimes<T>(value: T): T {
  if (Array.isArray(value)) return value.map((v) => withIsoTimes(v)) as T;
  if (value === null || typeof value !== "object") return value;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    out[k] = TIME_KEYS.has(k) && typeof v === "number" ? isoBkk(v) : withIsoTimes(v);
  }
  return out as T;
}

// ── ตัวช่วยฝั่ง error ────────────────────────────────────────────────────────

/**
 * enrichBadRequest — เติม "ค่าที่ใช้ได้จริง" ลงในข้อความ error
 *
 * นี่คือส่วนที่ทำให้ model แก้ให้ผู้ใช้ได้เองในเทิร์นเดียว: บอกว่า status ผิดเฉย ๆ
 * model ต้องเดาต่อว่าคอลัมน์ชื่ออะไรได้บ้าง แต่ถ้าแนบรายชื่อคอลัมน์จริงไปด้วย
 * มันจะยิงใหม่ให้ถูกได้ทันทีโดยไม่ต้องถามผู้ใช้
 */
async function enrichBadRequest(
  ctx: ToolContext,
  err: ApiError,
  projectKey: string | undefined,
): Promise<string> {
  if (err.code !== "BAD_REQUEST" || projectKey === undefined) return "";

  const m = err.message;
  if (/status|คอลัมน์/i.test(m)) {
    const board = await ctx.client.get<Board>(`/api/v1/projects/${projectKey}/board`);
    if (board.ok) {
      return `\n\nคอลัมน์ที่มีจริงในโปรเจกต์ ${projectKey}: ${board.data.columns.map((c) => `"${c.name}"`).join(", ")}`;
    }
  }
  if (/assignee|mention|สมาชิก|อีเมล/i.test(m)) {
    const members = await ctx.client.get<Page<Member>>(
      `/api/v1/projects/${projectKey}/members`,
    );
    if (members.ok) {
      return `\n\nอีเมลที่ใช้ได้ในโปรเจกต์ ${projectKey}: ${members.data.data.map((x) => x.email).join(", ")}`;
    }
  }
  if (/label|ป้าย/i.test(m)) {
    const labels = await ctx.client.get<Label[]>(`/api/v1/projects/${projectKey}/labels`);
    if (labels.ok) {
      return `\n\nlabel ที่มีจริงในโปรเจกต์ ${projectKey}: ${labels.data.map((l) => l.name).join(", ") || "(ยังไม่มี label เลย)"}`;
    }
  }
  return "";
}

/** ทางลัด: แปลง Result ที่ล้มเหลวเป็น ToolResult พร้อมข้อมูลเสริม */
async function failFrom(
  ctx: ToolContext,
  err: ApiError,
  hint: string,
  projectKey?: string,
  opts: { instead?: string } = {},
): Promise<ToolResult> {
  const extra = await enrichBadRequest(ctx, err, projectKey);
  return fail(describeError(err, hint, opts) + extra);
}

/** tool ที่ใช้แทน get_tickets / list_activity ได้บนเซิร์ฟเวอร์ที่ยังไม่มีเส้นของ ART-279 (ดู describeError) */
const READ_FALLBACK = { instead: "get_ticket / list_comments" };

/**
 * requireProjectKey — arg → env → ข้อความบอกวิธีหาค่า
 * ⚠️ ห้าม hardcode project key ใด ๆ ในโค้ดนี้ (decision 5)
 */
function requireProjectKey(
  ctx: ToolContext,
  arg: unknown,
): { ok: true; key: string } | { ok: false; res: ToolResult } {
  const fromArg = typeof arg === "string" && arg.trim() !== "" ? arg.trim() : undefined;
  const key = fromArg ?? ctx.cfg.projectKey;
  if (key === undefined) {
    return {
      ok: false,
      res: fail(
        "ไม่ได้ระบุ projectKey และไม่ได้ตั้ง ARTEMIS_PROJECT_KEY ไว้ใน .mcp.local.json — " +
          "เรียก list_projects เพื่อดูรหัสโปรเจกต์ที่เข้าถึงได้ แล้วส่ง projectKey มาด้วย",
      ),
    };
  }
  return { ok: true, key };
}

const str = (v: unknown): string | undefined =>
  typeof v === "string" && v.trim() !== "" ? v.trim() : undefined;

const num = (v: unknown): number | undefined => (typeof v === "number" ? v : undefined);
const bool = (v: unknown): string | undefined => (typeof v === "boolean" ? String(v) : undefined);

/** ใส่ลิงก์หน้าเว็บถ้าตั้ง ARTEMIS_SITE_URL ไว้ (ไม่ตั้ง = ไม่เดา) */
function withUrl(cfg: Config, key: string, line: string): string {
  const u = ticketUrl(cfg, key);
  return u === undefined ? line : `${line} · ${u}`;
}

