  /** ดึงรายชื่อ sprint จริงมาแนบในข้อความ error ของ move_to_sprint */
  async function listSprintNames(projectKey: string | undefined): Promise<string> {
    if (projectKey === undefined) return "";
    const res = await client.get<Page<Sprint>>(`/api/v1/projects/${projectKey}/sprints`);
    if (!res.ok || res.data.data.length === 0) return "";
    return (
      `\n\nsprint ที่มีจริงในโปรเจกต์ ${projectKey}:\n` +
      res.data.data.map((s) => `- ${s.name} (${s.status}) id=${s.id}`).join("\n")
    );
  }

