/**
 * stdio — entry point เดียวของ artemis-mcp (transport แบบ stdio)
 *
 * ไฟล์นี้คือที่**เดียว**ในแพ็กเกจที่แตะ node:fs / node:path / process
 * หน้าที่ทั้งหมดของมันคือ: อ่าน env → สร้าง client → ฉีดความสามารถอ่านไฟล์เข้า buildTools
 * → ลงทะเบียน tool กับ McpServer → ต่อ transport
 *
 * ⚠️ **ห้าม console.log ในไฟล์นี้และทั้งแพ็กเกจ** — stdout คือช่องสัญญาณ JSON-RPC
 * ข้อความหนึ่งบรรทัดที่หลุดลง stdout ทำให้ protocol พังทันทีโดยไม่มี error ที่อ่านรู้เรื่อง
 * ข้อความสำหรับมนุษย์ต้องไปที่ stderr ผ่าน logStderr() เท่านั้น
 */

import { readFile, realpath, stat } from "node:fs/promises";
import path, { basename, isAbsolute, resolve } from "node:path";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

import { loadConfig } from "./config";
import { createClient } from "./client";
import { makeIsInside } from "./fsGuard";
import { buildTools, configErrorTools, safeHandler, type LocalFs } from "./tools";
import { redactToken } from "./errors";

/** ต้องตรงกับ version ใน package.json เสมอ (version.test.ts บังคับ) — หน้า /settings/mcp ใช้ค่านั้นตั้งชื่อไฟล์ */
const VERSION = "0.8.0";

/** log สำหรับมนุษย์ — stderr เท่านั้น และ redact token เสมอ */
function logStderr(level: "error" | "debug", cfgLevel: string, message: string): void {
  if (cfgLevel === "silent") return;
  if (level === "debug" && cfgLevel !== "debug") return;
  process.stderr.write(`[artemis-mcp] ${redactToken(message)}\n`);
}

/** ความสามารถ "อ่านไฟล์ในเครื่อง" ตัวจริง — ถูกฉีดเข้า buildTools ผ่าน ToolContext.fs */
const nodeFs: LocalFs = {
  async stat(p) {
    const st = await stat(p);
    return { size: st.size, isFile: st.isFile() };
  },
  async read(p) {
    return new Uint8Array(await readFile(p));
  },
  resolve(p, base) {
    // path สัมบูรณ์อยู่แล้ว = ใช้ตามนั้น · path สัมพัทธ์ = อิงกับ base (ARTEMIS_UPLOAD_ROOT)
    // ถ้าไม่มี base ก็อิง cwd ของ MCP server ซึ่ง "ไม่ใช่" cwd ของผู้ใช้ —
    // จึงต้องรายงาน path ที่ resolve ได้กลับไปในทุกข้อความ error (ดู tools.ts ขั้น 1)
    if (isAbsolute(p)) return resolve(p);
    return base === undefined ? resolve(p) : resolve(base, p);
  },
  basename(p) {
    return basename(p);
  },
  realpath(p) {
    return realpath(p);
  },
  // node:path ของแพลตฟอร์มนี้ (win32 หรือ posix) — ตรรกะอยู่ใน fsGuard.ts ซึ่งเทสต์ทั้งสองแบบ
  isInside: makeIsInside(path),
};

async function main(): Promise<void> {
  const loaded = loadConfig(process.env);

  const server = new McpServer(
    { name: "artemis", version: VERSION },
    {
      instructions:
        "เครื่องมือจัดการงานของ Artemis (ระบบแทน Jira ของทีม) · เรียก list_projects ก่อน " +
        "ถ้ายังไม่รู้ว่ากำลังพูดถึงโปรเจกต์ไหน และเรียก get_board ก่อนสั่งเปลี่ยน status เสมอ " +
        "เพราะชื่อคอลัมน์เป็นค่าที่ทีมแก้เองได้",
    },
  );

  // config ปกติ = ใช้จริง · config พัง = ยังลงทะเบียน tool ครบทุกตัวแต่ให้ตอบวิธีแก้กลับไป
  // (ดูเหตุผลเต็มที่หัวไฟล์ config.ts — ตายตอน boot แปลว่า model ไม่เห็นอะไรเลย)
  const cfg = loaded.ok
    ? loaded.cfg
    : {
        // ค่าหลอกที่ไม่มีวันถูกใช้ เพราะ handler ทุกตัวถูกแทนที่ด้านล่างแล้ว
        apiUrl: "",
        token: "",
        projectKey: undefined,
        siteUrl: undefined,
        maxUploadBytes: 0,
        maxImageBytes: 0,
        maxInlineBytes: 0,
        allowedMime: [],
        uploadRoot: undefined,
        timeoutMs: 1,
        logLevel: "error" as const,
      };

  const base = buildTools({ client: createClient(cfg), cfg, fs: nodeFs });
  const tools = loaded.ok ? base : configErrorTools(base, loaded.message);

  if (!loaded.ok) logStderr("error", cfg.logLevel, `ตั้งค่าไม่ครบ: ${loaded.message}`);

  for (const t of tools) {
    server.registerTool(t.name, t.config, safeHandler(t.handler) as never);
  }

  logStderr("debug", cfg.logLevel, `ลงทะเบียน tool ${tools.length} ตัว · ปลายทาง ${cfg.apiUrl}`);

  await server.connect(new StdioServerTransport());
}

main().catch((e: unknown) => {
  process.stderr.write(
    `[artemis-mcp] เริ่มเซิร์ฟเวอร์ไม่สำเร็จ: ${redactToken(e instanceof Error ? e.stack ?? e.message : String(e))}\n`,
  );
  process.exit(1);
});
