/**
 * attachments — ตรรกะร่วมของ get_attachment และ get_ticket(includeImages)
 *
 * มี implementation เดียว ผู้เรียกสองคน · ถ้าปล่อยให้แต่ละ tool ทำเอง เมทริกซ์การ degrade
 * (รูปเล็ก→inline, รูปใหญ่→ลิงก์, ไม่ใช่รูป→ข้อความ) จะเพี้ยนกันคนละแบบทันทีที่มีคนแก้ที่เดียว
 */

import type { Config } from "./config";
import type { ArtemisClient } from "./client";
import { getBytes, type FetchLike } from "./client";
import type { Attachment } from "./types";
import type { ContentBlock } from "./content";
import { image, resourceLink, text, toBase64 } from "./content";
import { INLINE_IMAGE_MIME, formatBytes, isTextual } from "./mime";

/** ค่าปริยายของเพดานไฟล์ข้อความที่ยอมแปะลง context (ตัวอักษรมาก = token มาก) */
export const DEFAULT_TEXT_MAX_BYTES = 100_000;

export interface AttachmentDeps {
  client: ArtemisClient;
  cfg: Config;
  fetchImpl?: FetchLike;
}

/**
 * selectAttachment — เลือกไฟล์ 1 รายการจากตัวชี้ที่ผู้เรียกให้มา
 *
 * ลำดับ: attachmentId (เป๊ะ) → filename ตรงตัว → ไม่สนตัวพิมพ์ → substring ที่ชี้ได้ตัวเดียว
 * ไฟล์เดียวในงาน + ไม่ระบุอะไรเลย = ใช้ไฟล์นั้น (เป็นเจตนาที่ไม่กำกวม)
 *
 * คืน string = ข้อความอธิบายว่าทำไมเลือกไม่ได้ (ผู้เรียกเอาไปต่อกับรายการไฟล์ทั้งหมด)
 */
export function selectAttachment(
  list: Attachment[],
  sel: { attachmentId?: string; filename?: string },
): { ok: true; item: Attachment } | { ok: false; reason: string } {
  if (list.length === 0) return { ok: false, reason: "งานใบนี้ไม่มีไฟล์แนบเลย" };

  if (sel.attachmentId !== undefined && sel.attachmentId !== "") {
    const hit = list.find((a) => a.id === sel.attachmentId);
    return hit === undefined
      ? { ok: false, reason: `ไม่พบไฟล์แนบ id=${sel.attachmentId}` }
      : { ok: true, item: hit };
  }

  const name = sel.filename?.trim();
  if (name === undefined || name === "") {
    return list.length === 1
      ? { ok: true, item: list[0] }
      : { ok: false, reason: `งานใบนี้มีไฟล์แนบ ${list.length} รายการ — ต้องระบุ filename` };
  }

  const exact = list.filter((a) => a.filename === name);
  if (exact.length === 1) return { ok: true, item: exact[0] };

  const lower = name.toLowerCase();
  const ci = list.filter((a) => a.filename.toLowerCase() === lower);
  if (ci.length === 1) return { ok: true, item: ci[0] };

  const partial = list.filter((a) => a.filename.toLowerCase().includes(lower));
  if (partial.length === 1) return { ok: true, item: partial[0] };
  if (partial.length > 1) {
    return { ok: false, reason: `ชื่อ "${name}" ตรงกับไฟล์มากกว่า 1 รายการ` };
  }
  return { ok: false, reason: `ไม่พบไฟล์แนบชื่อ "${name}"` };
}

/** รายการไฟล์แบบบรรทัดเดียวต่อรายการ — ใช้ทั้งตอนสำเร็จและตอน error เพื่อให้ model เลือกใหม่ได้ */
export function describeAttachments(list: Array<{
  id: string;
  filename: string;
  mimeType: string;
  size: number;
}>): string {
  if (list.length === 0) return "ไม่มีไฟล์แนบ";
  return list
    .map((a) => `- ${a.filename} · ${a.mimeType} · ${formatBytes(a.size)} · id=${a.id}`)
    .join("\n");
}

/**
 * renderAttachment — ไฟล์ 1 รายการ → content block ตามเมทริกซ์การ degrade
 *
 * กติกาสำคัญ: **ห้าม throw และห้ามคืนลิสต์ว่าง** ทุกกรณีต้องได้ข้อความอธิบายอย่างน้อย 1 block
 * เพราะ tool ที่ตอบเงียบ ๆ ทำให้ model เดาว่าไฟล์ไม่มีอยู่ ซึ่งไม่จริง
 */
export async function renderAttachment(
  deps: AttachmentDeps,
  item: Attachment,
  opts: { ticketKey: string; maxImageBytes: number; textMaxBytes: number },
): Promise<ContentBlock[]> {
  const head = `${item.filename} (${item.mimeType}, ${formatBytes(item.size)}) จาก ${opts.ticketKey}`;

  if (item.url === null) {
    return [text(`${head} — เรคคอร์ดไฟล์แนบยังอยู่ แต่ตัวไฟล์ถูกลบออกจาก storage แล้ว จึงดึงมาแสดงไม่ได้`)];
  }

  const isInlineImage = INLINE_IMAGE_MIME.has(item.mimeType.toLowerCase());

  // รูปที่ใหญ่เกินเพดาน: ให้ลิงก์แทน ไม่ยัด base64 ทะลุ context
  if (isInlineImage && item.size > opts.maxImageBytes) {
    return [
      text(
        `${head} — ใหญ่เกินเพดานรูปที่แปะในแชตได้ (${formatBytes(opts.maxImageBytes)}) ` +
          "จึงส่งเป็นลิงก์แทน · ถ้าต้องการให้แสดงเป็นภาพจริง ให้เพิ่มค่า ARTEMIS_MAX_IMAGE_MB " +
          "ใน .mcp.local.json แล้ว restart MCP server",
      ),
      resourceLink(item.url, item.filename, item.mimeType),
    ];
  }

  if (!isInlineImage && !isTextual(item.mimeType)) {
    // pdf/zip/mp4/octet-stream — จงใจไม่ base64 (ไฟล์ 10 MB เป็น base64 คือ failure mode ที่เลี่ยงอยู่)
    const note = item.mimeType.toLowerCase().startsWith("image/")
      ? " · ชนิดรูปนี้แสดงเป็นภาพในแชตไม่ได้ — แปลงเป็น PNG/JPEG ก่อนถ้าต้องให้ดูด้วยตา"
      : "";
    return [text(`${head}${note}`), resourceLink(item.url, item.filename, item.mimeType)];
  }

  // ถึงตรงนี้ = รูปที่ inline ได้ หรือไฟล์ข้อความ → ต้องดึง bytes จริง
  const cap = isInlineImage ? opts.maxImageBytes : opts.textMaxBytes;
  const got = await getBytes(item.url, cap, deps.cfg.timeoutMs, deps.fetchImpl);
  if (!got.ok) {
    return [text(`${head} — ดึงไฟล์ไม่สำเร็จ: ${got.err.message}`)];
  }

  if (isInlineImage) {
    if (got.data.truncated) {
      // รูปที่ถูกตัดกลางคัน = ไฟล์เสีย ส่งไปก็แสดงไม่ได้ — บอกตรง ๆ ดีกว่า
      return [
        text(`${head} — ตัวไฟล์จริงใหญ่กว่าเพดาน ${formatBytes(cap)} จึงแสดงเป็นภาพไม่ได้`),
        resourceLink(item.url, item.filename, item.mimeType),
      ];
    }
    return [text(head), image(toBase64(got.data.bytes), item.mimeType)];
  }

  const body = new TextDecoder().decode(got.data.bytes);
  const marker = got.data.truncated
    ? `\n…[ตัดที่ ${cap}/${item.size} ไบต์ — ขอเพิ่มด้วย maxBytes]`
    : "";
  return [text(`${head}\n\n${body}${marker}`)];
}

/**
 * resolveAttachmentBlocks — วนรูปในงาน 1 ใบให้กลายเป็น block (ใช้โดย get_ticket includeImages)
 *
 * หยุดเมื่อชนอย่างใดอย่างหนึ่ง: จำนวนรูป (maxCount) หรืองบไบต์รวม (budgetBytes)
 * แล้ว **บอกเสมอว่าข้ามอะไรไปเพราะอะไร** — การเงียบทำให้ model คิดว่าเห็นครบแล้ว
 */
export async function resolveAttachmentBlocks(
  deps: AttachmentDeps,
  ticketKey: string,
  list: Attachment[],
  opts: { maxCount: number; budgetBytes: number; maxImageBytes: number },
): Promise<ContentBlock[]> {
  const images = list.filter((a) => INLINE_IMAGE_MIME.has(a.mimeType.toLowerCase()));
  if (images.length === 0) return [];

  const blocks: ContentBlock[] = [];
  const skipped: string[] = [];
  let used = 0;
  let shown = 0;

  for (const item of images) {
    if (shown >= opts.maxCount) {
      skipped.push(`${item.filename} (ชนเพดานจำนวนรูป ${opts.maxCount} ใบต่อครั้ง)`);
      continue;
    }
    if (item.size > opts.maxImageBytes) {
      skipped.push(`${item.filename} (ใหญ่เกิน ARTEMIS_MAX_IMAGE_MB = ${formatBytes(opts.maxImageBytes)})`);
      continue;
    }
    if (used + item.size > opts.budgetBytes) {
      skipped.push(`${item.filename} (งบรวมของครั้งนี้ ${formatBytes(opts.budgetBytes)} ไม่พอแล้ว)`);
      continue;
    }
    const rendered = await renderAttachment(deps, item, {
      ticketKey,
      maxImageBytes: opts.maxImageBytes,
      textMaxBytes: DEFAULT_TEXT_MAX_BYTES,
    });
    blocks.push(...rendered);
    used += item.size;
    shown += 1;
  }

  if (skipped.length > 0) {
    blocks.push(
      text(
        `ยังมีรูปที่ไม่ได้แสดงอีก ${skipped.length} ใบ:\n` +
          skipped.map((s) => `- ${s}`).join("\n") +
          "\nเรียก get_attachment ทีละใบเพื่อดูรูปที่เหลือ",
      ),
    );
  }
  return blocks;
}
