/**
 * mime — เดาชนิดไฟล์โดยไม่พึ่ง dependency ภายนอก
 *
 * ลำดับความน่าเชื่อถือ: ค่าที่ผู้เรียกระบุมา → magic bytes (ไบต์ต้นไฟล์) → นามสกุล → octet-stream
 * เอา magic bytes มาก่อนนามสกุลเพราะนามสกุลเป็นแค่ "ความตั้งใจของคนตั้งชื่อ"
 * ส่วนไบต์ต้นไฟล์คือของจริง (ไฟล์ชื่อ .txt ที่ข้างในเป็น PNG มีอยู่จริงและเกิดบ่อย)
 */

const EXTENSION_MIME: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  svg: "image/svg+xml",
  bmp: "image/bmp",
  tif: "image/tiff",
  tiff: "image/tiff",
  heic: "image/heic",
  avif: "image/avif",
  pdf: "application/pdf",
  zip: "application/zip",
  gz: "application/gzip",
  mp4: "video/mp4",
  mov: "video/quicktime",
  mp3: "audio/mpeg",
  wav: "audio/wav",
  txt: "text/plain",
  log: "text/plain",
  md: "text/markdown",
  csv: "text/csv",
  html: "text/html",
  css: "text/css",
  js: "text/javascript",
  ts: "text/plain",
  json: "application/json",
  xml: "application/xml",
  yml: "text/yaml",
  yaml: "text/yaml",
};

/** ชนิดรูปที่ฝั่งแชตแสดงเป็นภาพได้จริง (raster) — นอกลิสต์นี้ต้อง degrade เป็นข้อความ */
export const INLINE_IMAGE_MIME = new Set([
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
]);

/** true = เนื้อหาอ่านเป็นข้อความได้ จึงส่งเป็น text block ได้ (ตัดความยาวตาม maxBytes) */
export function isTextual(mime: string): boolean {
  const m = mime.toLowerCase();
  return (
    m.startsWith("text/") ||
    m === "application/json" ||
    m === "application/xml" ||
    m === "image/svg+xml" || // SVG คือ XML ไม่ใช่ raster — ส่งเป็นข้อความมีประโยชน์กว่า
    m.endsWith("+json") ||
    m.endsWith("+xml")
  );
}

export function extensionOf(filename: string): string {
  const dot = filename.lastIndexOf(".");
  return dot === -1 ? "" : filename.slice(dot + 1).toLowerCase();
}

function startsWith(bytes: Uint8Array, sig: number[], offset = 0): boolean {
  if (bytes.length < offset + sig.length) return false;
  return sig.every((b, i) => bytes[offset + i] === b);
}

/** อ่าน magic bytes · คืน undefined ถ้าไม่รู้จักลายเซ็นนี้ */
export function sniffMime(bytes: Uint8Array): string | undefined {
  if (startsWith(bytes, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return "image/png";
  if (startsWith(bytes, [0xff, 0xd8, 0xff])) return "image/jpeg";
  if (startsWith(bytes, [0x47, 0x49, 0x46, 0x38])) return "image/gif";
  // WebP = RIFF....WEBP (ต้องเช็คทั้งสองก้อน ไม่งั้นชนกับ WAV/AVI ที่ก็ขึ้นต้นด้วย RIFF)
  if (startsWith(bytes, [0x52, 0x49, 0x46, 0x46]) && startsWith(bytes, [0x57, 0x45, 0x42, 0x50], 8))
    return "image/webp";
  if (startsWith(bytes, [0x52, 0x49, 0x46, 0x46]) && startsWith(bytes, [0x57, 0x41, 0x56, 0x45], 8))
    return "audio/wav";
  if (startsWith(bytes, [0x25, 0x50, 0x44, 0x46])) return "application/pdf";
  if (startsWith(bytes, [0x50, 0x4b, 0x03, 0x04])) return "application/zip";
  if (startsWith(bytes, [0x1f, 0x8b])) return "application/gzip";
  // ISO Base Media (mp4/mov) — 4 ไบต์แรกคือความยาวกล่อง จึงเช็คคำว่า "ftyp" ที่ offset 4
  if (startsWith(bytes, [0x66, 0x74, 0x79, 0x70], 4)) return "video/mp4";
  return undefined;
}

/** รวมสามแหล่งตามลำดับความน่าเชื่อถือ */
export function detectMime(
  filename: string,
  head: Uint8Array,
  explicit?: string,
): string {
  if (explicit !== undefined && explicit.trim() !== "") return explicit.trim();
  const sniffed = sniffMime(head);
  if (sniffed !== undefined) return sniffed;
  return EXTENSION_MIME[extensionOf(filename)] ?? "application/octet-stream";
}

/**
 * matchesAllowlist — เทียบกับ ARTEMIS_ALLOWED_MIME ที่รองรับ wildcard แบบ `image/*`
 * allowlist ว่าง = อนุญาตทุกชนิด (ไม่ได้ตั้ง = ไม่ได้ตั้งใจจำกัด)
 */
export function matchesAllowlist(mime: string, allowlist: string[]): boolean {
  if (allowlist.length === 0) return true;
  const m = mime.toLowerCase();
  return allowlist.some((rule) => {
    const r = rule.toLowerCase();
    if (r === "*" || r === "*/*") return true;
    if (r.endsWith("/*")) return m.startsWith(r.slice(0, -1));
    return m === r;
  });
}

/** ขนาดไฟล์แบบคนอ่านออก — ใช้ในข้อความ error ทุกจุดที่พูดถึงเพดาน */
export function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}
