/**
 * config — อ่านตัวแปรแวดล้อม (environment variable) แล้วแปลงเป็น Config
 *
 * ⚠️ กติกาเหล็ก: ฟังก์ชันนี้ **ไม่ throw** ไม่ว่าค่าจะพังแค่ไหน
 *
 * เหตุผล: ถ้า MCP server ตายตั้งแต่ตอน start ผู้ใช้จะเห็นแค่ "MCP server failed" ลอย ๆ
 * และ **ตัว AI model ไม่เห็นอะไรเลย** จึงช่วยบอกไม่ได้ว่าต้องแก้ตัวแปรไหน
 * เราจึงเลือกให้ boot สำเร็จเสมอ แล้วลงทะเบียน tool ครบทุกตัว — เมื่อถูกเรียกจึงตอบกลับ
 * เป็นข้อความที่ "ทำตามแล้วแก้ได้จริง" (actionable) ซึ่ง model อ่านแล้วบอกผู้ใช้ต่อได้
 */

/** รูปแบบ token ที่ Artemis ออกให้ — `art_` ตามด้วยเลขฐานสิบหก 64 ตัว (ดู convex/model/apiToken.ts) */
const TOKEN_PATTERN = /^art_[0-9a-f]{64}$/;

export interface Config {
  /** URL ฐานของ Convex HTTP Actions เช่น https://xxx.convex.site (ไม่มี / ปิดท้าย) */
  apiUrl: string;
  /** API token — ห้าม echo ค่านี้ออกไปในข้อความใด ๆ */
  token: string;
  /** projectKey ปริยาย เมื่อ tool ไม่ได้ระบุมา · undefined = ต้องระบุทุกครั้ง */
  projectKey: string | undefined;
  /** URL หน้าเว็บ ใช้ประกอบลิงก์ `${siteUrl}/browse/{key}` · undefined = ไม่ใส่ลิงก์ */
  siteUrl: string | undefined;
  maxUploadBytes: number;
  maxImageBytes: number;
  maxInlineBytes: number;
  /** allowlist ชนิดไฟล์ที่ยอมให้อัปโหลด · [] = อนุญาตทุกชนิด */
  allowedMime: string[];
  /** ถ้าตั้ง = upload_attachment อ่านไฟล์ได้เฉพาะใต้โฟลเดอร์นี้ */
  uploadRoot: string | undefined;
  timeoutMs: number;
  logLevel: "silent" | "error" | "debug";
}

export type ConfigResult = { ok: true; cfg: Config } | { ok: false; message: string };

export type Env = Record<string, string | undefined>;

const MB = 1024 * 1024;

/** อ่านค่าตัวเลขหน่วย MB · ค่าที่ไม่ใช่ตัวเลขบวกให้ถอยกลับไปใช้ค่าปริยาย (ไม่ล้มทั้ง server) */
function readMb(env: Env, name: string, defaultMb: number): number {
  const raw = env[name];
  if (raw === undefined || raw.trim() === "") return defaultMb * MB;
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n * MB) : defaultMb * MB;
}

function readInt(env: Env, name: string, dflt: number): number {
  const raw = env[name];
  if (raw === undefined || raw.trim() === "") return dflt;
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : dflt;
}

/** ตัด / ปิดท้ายออก เพื่อให้ต่อ path ได้โดยไม่เกิด // ซ้อน */
function trimSlash(u: string): string {
  return u.replace(/\/+$/, "");
}

export function loadConfig(env: Env): ConfigResult {
  const apiUrl = env.ARTEMIS_API_URL?.trim();
  if (apiUrl === undefined || apiUrl === "") {
    return {
      ok: false,
      message:
        "ยังไม่ได้ตั้ง ARTEMIS_API_URL — ค่านี้คือ URL ฐานของ Convex ของ Artemis " +
        "(หน้าตาแบบ https://<deployment>.convex.site ซึ่งคนละที่กับหน้าเว็บ) " +
        "ตั้งได้ในช่อง env ของ .mcp.local.json แล้ว restart MCP server",
    };
  }
  if (!/^https?:\/\//.test(apiUrl)) {
    return {
      ok: false,
      message: `ARTEMIS_API_URL ต้องขึ้นต้นด้วย http:// หรือ https:// (ค่าปัจจุบันคือ "${apiUrl}")`,
    };
  }

  const token = env.ARTEMIS_API_TOKEN?.trim();
  if (token === undefined || token === "") {
    return {
      ok: false,
      message:
        "ยังไม่ได้ตั้ง ARTEMIS_API_TOKEN — สร้าง token ได้ที่หน้า /settings/api-tokens (เมนูบัญชี → API Tokens ของฉัน) " +
        "ของ Artemis แล้วใส่ในช่อง env ของ .mcp.local.json (ค่าจะแสดงครั้งเดียวตอนสร้าง)",
    };
  }
  if (!TOKEN_PATTERN.test(token)) {
    // ⚠️ จงใจไม่ echo ค่า token ลงในข้อความ — ข้อความนี้จะถูกส่งเข้า context ของ model
    return {
      ok: false,
      message:
        "รูปแบบ ARTEMIS_API_TOKEN ไม่ถูกต้อง — ต้องขึ้นต้นด้วย art_ ตามด้วยเลขฐานสิบหก 64 ตัว " +
        "(ค่าที่ตั้งไว้ไม่ตรงรูปแบบนี้) สร้างใหม่ที่หน้า /settings/api-tokens (เมนูบัญชี → API Tokens ของฉัน)",
    };
  }

  const logLevelRaw = env.ARTEMIS_LOG_LEVEL?.trim();
  const logLevel =
    logLevelRaw === "silent" || logLevelRaw === "debug" || logLevelRaw === "error"
      ? logLevelRaw
      : "error";

  const projectKey = env.ARTEMIS_PROJECT_KEY?.trim();
  const siteUrl = env.ARTEMIS_SITE_URL?.trim();
  const uploadRoot = env.ARTEMIS_UPLOAD_ROOT?.trim();

  return {
    ok: true,
    cfg: {
      apiUrl: trimSlash(apiUrl),
      token,
      // ห้าม hardcode project key ใด ๆ ในโค้ด — ค่ามาจาก env หรือจาก arg ของ tool เท่านั้น
      projectKey: projectKey === "" ? undefined : projectKey,
      siteUrl: siteUrl === undefined || siteUrl === "" ? undefined : trimSlash(siteUrl),
      maxUploadBytes: readMb(env, "ARTEMIS_MAX_UPLOAD_MB", 25),
      maxImageBytes: readMb(env, "ARTEMIS_MAX_IMAGE_MB", 4),
      maxInlineBytes: readMb(env, "ARTEMIS_MAX_INLINE_MB", 8),
      allowedMime: (env.ARTEMIS_ALLOWED_MIME ?? "")
        .split(",")
        .map((s) => s.trim())
        .filter((s) => s !== ""),
      uploadRoot: uploadRoot === "" ? undefined : uploadRoot,
      timeoutMs: readInt(env, "ARTEMIS_TIMEOUT_MS", 30_000),
      logLevel,
    },
  };
}

/**
 * ticketUrl — ลิงก์หน้าเว็บของงาน · รูปแบบตรงกับ convex/email.ts (`${SITE_URL}/browse/{key}`)
 * ไม่ตั้ง ARTEMIS_SITE_URL = คืน undefined (ไม่เดา — Convex site URL คนละโดเมนกับหน้าเว็บ)
 */
export function ticketUrl(cfg: Config, key: string): string | undefined {
  return cfg.siteUrl === undefined ? undefined : `${cfg.siteUrl}/browse/${key}`;
}
